<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('CancelRequest') }}
                        </h5>
                        <button v-on:click="closeRejectPopUp" class="close"><i class="fa fa-times"
                                aria-hidden="true"></i></button>
                    </div>
                    <div class="border p-3">

                        <div class="row mb-2">

                            <div class="col-md-6 col-lg-4">
                                <div class="form-group"><label><b> {{ $t('ItemName') }}:</b> {{ details.AssetGroup
                                        }}</label>
                                </div>
                            </div>
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group"><label><b>{{ $t("FromTime") }}:</b> {{
                                    $options.filters.formatDateTimeMMDDYY(details.FromTime) }}</label></div>
                            </div>
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group"><label><b>{{ $t("ToTime") }}:</b> {{
                                    $options.filters.formatDateTimeMMDDYY(details.ToTime) }}</label></div>
                            </div>

                        </div>

                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema"
                            v-on:OnSubmit="onSubmit"></dynamic-form>
                    </div>

                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataService from "../../service/DataService";

export default {

    props: {
        specificDetails: {
            type: Object
        }

    },

    data() {

        return {
            details: {},
            isLoading:false,
            FormSchema: [
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",
                            label: this.$t('Comment'),
                            name: "Reject",
                            value: "",
                            placeholder: "",
                            validationRules: { "required": true, max: 250 },
                        }

                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>" + this.$t('Save'),
                },
                {
                    type: "button",
                    class: "btn btn-danger text-white",
                    text: "&nbsp;<i class='fa fa-close pr-2'></i>" + this.$t('Cancel'),
                    onClick: this.closeRejectPopUp
                }
            ],

        }
    },


    created: function () {
        var vm = this;
        vm.details = vm.specificDetails;
        console.log("details", vm.details);
    },


    methods: {

        closeRejectPopUp: function () {
            this.$emit('closeRejectPopUp');

        },

        onSubmit: function (values) {

            var vm = this;
            vm.isLoading=true;
            let content = [];
            let obj = {
                AssetUniqueName: vm.details.AssetGroup,
                AssetCatalogName: vm.details.CatalogName,
                AssetQuantity: vm.details.RequestQuantity
            }
           
            content.push(obj);

            let mainObj = JSON.stringify(content);
            var url = `batchId=${vm.details.RequisitionBatchId}&requisitionCancelledBy=USER&comment=${values.Reject}&requisitionId=${vm.details.RequisitionId}&tableContent=${mainObj}`

            DataService.UpdateRequisitionStatusCheckout(url).then((response) => {
                if (response.data == true||response.data.statuS_CODE == true) {
                    vm.closeRejectPopUp();
                    vm.ShowAlert(this.$t(" Status Update Successfully "), "success", this.$t('Alert'));                   
                    vm.isLoading=false;
                    vm.$parent.FetchData();

                } else {                    
                    vm.ShowAlert(this.$t(" Something Went Wrong "), "failure", this.$t('Alert'));
                    vm.isLoading=false;
                }
            });


        }
    }







}
</script>

<style></style>